INSERT INTO "public"."messages" ("id", "expediteur_id", "destinataire_id", "contenu", "created_at", "lu", "annonce_id", "is_alert") VALUES
	('34e049f3-7fdd-4497-aaf7-5c25b8c5d907', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Oui le loyer est charges comprises (eau, électricité, internet). Tout est inclus dans le prix affiché sur STERNY.', '2026-02-26 08:00:00+00', true, NULL, false),
	('0f7a222a-24e2-460c-adc7-cb62f33960f7', 'c2e5770e-65ca-4b15-acc0-95a3d21849c1', '613ed0a0-b7ce-4c86-9736-78e71ad65d80', 'toujours ok pour demain !?', '2026-04-09 22:53:11.643825+00', false, NULL, false),
	('1878be26-dec1-4e65-ba58-573b75f280db', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'Bonjour Marie, je suis Lucas, etudiant en alternance a Rennes. Votre annonce pour le studio m''interesse beaucoup. Est-il toujours disponible ?', '2026-02-23 14:54:07.277933+00', true, NULL, false),
	('d7306c5a-d866-4f29-a44a-57f1311403cb', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'Super, oui je suis disponible. Est-ce que samedi matin vers 10h ca vous irait ?', '2026-02-24 11:54:07.277933+00', true, NULL, false),
	('b858bd7b-906e-4d1f-8eff-996fce992107', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'Merci beaucoup, je note. Est-ce que le loyer inclut les charges ?', '2026-02-25 13:54:07.277933+00', true, NULL, false),
	('3c440976-57c9-466e-821c-377214fcdf05', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Bonjour Lucas, oui le studio est toujours disponible. Il fait 25m2, meuble, avec WiFi. Vous seriez disponible pour une visite ?', '2026-02-24 08:54:07.277933+00', true, NULL, false),
	('ac1639e1-f4a8-4d3f-a4cd-537281e8d987', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Samedi 10h parfait. Le studio est au 12 rue de la Paix, 2eme etage. Sonnez a Leroy.', '2026-02-25 09:54:07.277933+00', true, NULL, false),
	('448d263f-33e6-487d-8f52-8e7b5514bbe0', 'f8bb1766-305d-45bd-9c60-0b2b6e07b29e', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Super, a samedi alors. N''hesite pas si tu as d''autres questions.', '2026-02-26 16:26:51.623203+00', true, NULL, false),
	('68ebfc4a-048a-4490-8f5a-fe0b62bae81c', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', '2cb8d219-b3fe-4cc4-af9d-642b76a5b349', 'Salut Emma, tu es aussi en alternance a Rennes ? On est peut-etre dans la meme ecole', '2026-02-25 21:00:03.374799+00', true, NULL, false),
	('61613fa7-374b-4a96-ae8a-b872517eb1f1', '2cb8d219-b3fe-4cc4-af9d-642b76a5b349', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Salut Lucas, oui je suis a Rennes, a l''ESIR en informatique. Et toi ?', '2026-02-25 22:40:03.374799+00', true, NULL, false),
	('366c2360-ef9d-4e66-ae00-9f02124ba3b4', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', '2cb8d219-b3fe-4cc4-af9d-642b76a5b349', 'Moi je suis a l''INSA, en genie civil. Tu as trouve un logement facilement ?', '2026-02-26 02:00:03.374799+00', true, NULL, false),
	('ddf56111-97aa-4e9d-a748-148e8b08d269', '2cb8d219-b3fe-4cc4-af9d-642b76a5b349', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Pas trop, j''ai galere 2 semaines. STERNY m''a bien aide. Tu cherches encore ?', '2026-02-26 03:40:03.374799+00', true, NULL, false),
	('6b017d15-2d8d-4b7c-8e73-27d480c40959', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', '2cb8d219-b3fe-4cc4-af9d-642b76a5b349', 'J''ai une visite samedi pour un studio, on verra bien', '2026-02-26 05:20:03.374799+00', true, NULL, false),
	('dc4be5bb-fb67-4ee0-a4b5-50958b146d5c', '613ed0a0-b7ce-4c86-9736-78e71ad65d80', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', 'Hey Lucas, c''est Thomas. J''ai vu que tu cherchais aussi a Rennes. Tu as des bons plans ?', '2026-02-26 08:40:03.374799+00', true, NULL, false),
	('939bc036-c665-423a-9276-e9d0de2b9a1d', 'b06fde61-c56d-4d38-9534-dfc0d7029cb8', '613ed0a0-b7ce-4c86-9736-78e71ad65d80', 'Salut Thomas, regarde dans le quartier Sainte-Anne, il y a pas mal de studios', '2026-02-26 09:00:03.374799+00', true, NULL, false),
